SELECT id, user_id, username, ip_address, user_agent, success, failure_reason, created_at
FROM login_history
WHERE username = #{username}
ORDER BY created_at DESC
LIMIT #{limit}

SELECT id, user_id AS userId, username, ip_address AS ipAddress, user_agent AS userAgent,
       success, failure_reason AS failureReason, created_at AS createdAt
FROM login_history

    AND user_id = #{userId}
    AND username ILIKE '%' || #{username} || '%'
    AND success = #{success}
    AND created_at >= #{from}
    AND created_at < #{to}
    AND ip_address = #{ipAddress}

ORDER BY

    created_at ASC
    username ASC
    username DESC
    created_at DESC

LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM login_history

    AND user_id = #{userId}
    AND username ILIKE '%' || #{username} || '%'
    AND success = #{success}
    AND created_at >= #{from}
    AND created_at < #{to}
    AND ip_address = #{ipAddress}

SELECT id, user_id AS userId, username, ip_address AS ipAddress, user_agent AS userAgent,
       success, failure_reason AS failureReason, created_at AS createdAt
FROM login_history
WHERE user_id = #{userId}
ORDER BY created_at DESC
LIMIT #{limit} OFFSET #{offset}
